public ISmsProvider Resolve(SmsRoutingContext context)
{
    var provider_name = context.ExplicitProvider ?? _options.DefaultProvider;

    if (string.IsNullOrWhiteSpace(provider_name))
        throw new SmsBridgeException(
            "No provider could be resolved. Set 'SmsBridge:DefaultProvider' in configuration.");

    if (!_providers.TryGetValue(provider_name, out var provider))
        throw new SmsBridgeException(
            $"Provider '{provider_name}' is not registered. Registered: [{string.Join(", ", _providers.Keys)}].");

    return provider;
}
